// Smash Arena client: networking, screens, input, rendering.
(function () {
  const { PHYS, CHARACTERS, MAPS } = SHARED;
  const { drawFighter } = FIGHTERS;
  const { drawBackground, drawPlatforms, drawPreview } = MAPRENDER;

  const $ = (sel) => document.querySelector(sel);
  const $$ = (sel) => [...document.querySelectorAll(sel)];

  // ---------------------------------------------------------------------------
  // State
  // ---------------------------------------------------------------------------
  let ws = null;
  let myId = null;
  let phase = 'join';
  let roster = [];            // lobby/select state from server
  let mapKey = null;
  let winnerId = null;
  let countdownEnd = 0;

  const snaps = [];           // snapshot buffer for interpolation
  let clockOffset = null;     // serverTime - localTime (smoothed)
  const animState = new Map();// id -> {anim, t0(local), animT0}
  const particles = [];
  let shake = 0;
  let banner = { text: '', until: 0, color: '#fff' };
  const PLAYER_HUES = ['#ff5252', '#448aff', '#ffd740', '#69f0ae', '#e040fb', '#ff6e40', '#18ffff', '#b2ff59'];

  function localTime() { return performance.now() / 1000; }

  // ---------------------------------------------------------------------------
  // Audio (synthesized)
  // ---------------------------------------------------------------------------
  let AC = null, masterGain = null, musicGain = null, musicOn = true, musicTimer = null;

  function initAudio() {
    if (AC) return;
    AC = new (window.AudioContext || window.webkitAudioContext)();
    masterGain = AC.createGain(); masterGain.gain.value = 0.5; masterGain.connect(AC.destination);
    musicGain = AC.createGain(); musicGain.gain.value = 0.14; musicGain.connect(masterGain);
    startMusic();
  }

  function tone(freq, dur, type = 'square', vol = 0.25, slide = 0) {
    if (!AC) return;
    const o = AC.createOscillator(), g = AC.createGain();
    o.type = type; o.frequency.value = freq;
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), AC.currentTime + dur);
    g.gain.setValueAtTime(vol, AC.currentTime);
    g.gain.exponentialRampToValueAtTime(0.001, AC.currentTime + dur);
    o.connect(g); g.connect(masterGain);
    o.start(); o.stop(AC.currentTime + dur);
  }

  function noise(dur, vol = 0.3, freq = 1000) {
    if (!AC) return;
    const len = Math.floor(AC.sampleRate * dur);
    const buf = AC.createBuffer(1, len, AC.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / len);
    const src = AC.createBufferSource(); src.buffer = buf;
    const f = AC.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = freq;
    const g = AC.createGain(); g.gain.value = vol;
    src.connect(f); f.connect(g); g.connect(masterGain);
    src.start();
  }

  const SFX = {
    click: () => tone(700, 0.06, 'square', 0.15),
    hit: (heavy) => { noise(0.12, 0.4, heavy ? 500 : 900); tone(heavy ? 90 : 140, 0.15, 'sine', 0.5, -40); },
    swing: () => noise(0.08, 0.12, 2400),
    jump: () => tone(300, 0.12, 'sine', 0.2, 250),
    ko: () => { tone(500, 0.5, 'sawtooth', 0.3, -440); noise(0.4, 0.5, 700); },
    countdown: () => tone(440, 0.12, 'square', 0.25),
    go: () => { tone(660, 0.25, 'square', 0.3); tone(880, 0.35, 'square', 0.2); },
    win: () => { [523, 659, 784, 1047].forEach((f, i) => setTimeout(() => tone(f, 0.3, 'square', 0.25), i * 130)); }
  };

  const MELODY = [0, 3, 7, 10, 12, 10, 7, 3, 0, 3, 7, 12, 15, 12, 10, 7];
  let melodyStep = 0;
  function startMusic() {
    if (musicTimer) return;
    musicTimer = setInterval(() => {
      if (!AC || !musicOn) return;
      const base = phase === 'battle' ? 220 : 165;
      const semi = MELODY[melodyStep % MELODY.length];
      const f = base * Math.pow(2, semi / 12);
      const o = AC.createOscillator(), g = AC.createGain();
      o.type = 'triangle'; o.frequency.value = f;
      g.gain.setValueAtTime(0.5, AC.currentTime);
      g.gain.exponentialRampToValueAtTime(0.001, AC.currentTime + 0.22);
      o.connect(g); g.connect(musicGain);
      o.start(); o.stop(AC.currentTime + 0.24);
      if (melodyStep % 4 === 0) { // bass
        const b = AC.createOscillator(), bg = AC.createGain();
        b.type = 'sine'; b.frequency.value = base / 2;
        bg.gain.setValueAtTime(0.6, AC.currentTime);
        bg.gain.exponentialRampToValueAtTime(0.001, AC.currentTime + 0.4);
        b.connect(bg); bg.connect(musicGain);
        b.start(); b.stop(AC.currentTime + 0.42);
      }
      melodyStep++;
    }, 250);
  }

  // ---------------------------------------------------------------------------
  // Networking
  // ---------------------------------------------------------------------------
  function connect(name) {
    const proto = location.protocol === 'https:' ? 'wss' : 'ws';
    ws = new WebSocket(`${proto}://${location.host}`);
    ws.onopen = () => ws.send(JSON.stringify({ type: 'join', name }));
    ws.onmessage = (e) => handle(JSON.parse(e.data));
    ws.onclose = () => {
      showScreen('join');
      $('#join-error').textContent = 'Disconnected from server. Refresh to rejoin.';
    };
  }

  function send(msg) { if (ws && ws.readyState === 1) ws.send(JSON.stringify(msg)); }

  function handle(msg) {
    switch (msg.type) {
      case 'welcome':
        myId = msg.id;
        break;

      case 'state': {
        const prev = phase;
        phase = msg.phase;
        roster = msg.players;
        winnerId = msg.winnerId;
        if (msg.map) mapKey = msg.map;
        if (phase === 'lobby') showScreen('lobby');
        else if (phase === 'charselect') showScreen('char');
        else if (phase === 'mapselect') showScreen('map');
        else if (phase === 'battle') showScreen('game');
        else if (phase === 'victory') { showScreen('game'); showVictory(); }
        renderLobby(); renderCharSelect(); renderMapSelect(); renderHUD(null);
        if (prev !== phase && phase === 'victory') SFX.win();
        break;
      }

      case 'battleStart':
        mapKey = msg.map;
        snaps.length = 0;
        animState.clear();
        particles.length = 0;
        clockOffset = null;
        $('#victory-overlay').classList.add('hidden');
        showScreen('game');
        break;

      case 'snap': {
        const t = localTime();
        const off = msg.t - t;
        clockOffset = clockOffset === null ? off : clockOffset * 0.95 + off * 0.05;
        msg.local = t;
        snaps.push(msg);
        if (snaps.length > 30) snaps.shift();
        renderHUD(msg);
        handleCountdownAudio(msg.countdown);
        break;
      }

      case 'event': handleEvent(msg); break;
    }
  }

  let lastCountdownInt = -1;
  function handleCountdownAudio(cd) {
    const i = Math.ceil(cd);
    if (i !== lastCountdownInt) {
      if (i > 0 && i <= 3) SFX.countdown();
      else if (i === 0 && lastCountdownInt === 1) { SFX.go(); flashBanner('GO!', '#7CFC00', 0.8); }
      lastCountdownInt = i;
    }
  }

  function handleEvent(ev) {
    switch (ev.kind) {
      case 'hit': {
        SFX.hit(ev.heavy);
        shake = Math.min(18, shake + (ev.heavy ? 12 : 6));
        const n = ev.heavy ? 18 : 10;
        for (let i = 0; i < n; i++) {
          const a = Math.random() * Math.PI * 2;
          const sp = 120 + Math.random() * (ev.heavy ? 420 : 260);
          particles.push({
            x: ev.x, y: ev.y, vx: Math.cos(a) * sp + ev.face * 120, vy: Math.sin(a) * sp - 80,
            life: 0.45, max: 0.45, size: 3 + Math.random() * 4,
            color: ev.heavy ? '#ffcc33' : '#ffffff', grav: 600
          });
        }
        break;
      }
      case 'ko': {
        SFX.ko();
        shake = 24;
        const px = Math.max(-1050, Math.min(1050, ev.x));
        const py = Math.max(-780, Math.min(650, ev.y));
        for (let i = 0; i < 40; i++) {
          const a = Math.random() * Math.PI * 2;
          const sp = 200 + Math.random() * 600;
          particles.push({
            x: px, y: py, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
            life: 0.9, max: 0.9, size: 4 + Math.random() * 6,
            color: ['#ff5252', '#ffd740', '#ffffff', '#40c4ff'][i % 4], grav: 300
          });
        }
        const victim = roster.find(p => p.id === ev.id);
        flashBanner(`${victim ? victim.name : 'Fighter'} KO'd!`, '#ff5252', 1.4);
        break;
      }
      case 'eliminated': {
        const v = roster.find(p => p.id === ev.id);
        flashBanner(`${v ? v.name : 'Fighter'} is ELIMINATED`, '#ff8a80', 2);
        break;
      }
      case 'djump':
        for (let i = 0; i < 6; i++) {
          particles.push({
            x: ev.x + (Math.random() - 0.5) * 30, y: ev.y, vx: (Math.random() - 0.5) * 80, vy: 60 + Math.random() * 60,
            life: 0.35, max: 0.35, size: 5, color: 'rgba(255,255,255,0.8)', grav: -100
          });
        }
        SFX.jump();
        break;
      case 'swing': SFX.swing(); break;
    }
  }

  function flashBanner(text, color, dur) {
    banner = { text, color, until: localTime() + dur };
  }

  // ---------------------------------------------------------------------------
  // Screens
  // ---------------------------------------------------------------------------
  function showScreen(name) {
    $$('.screen').forEach(s => s.classList.add('hidden'));
    $(`#screen-${name}`).classList.remove('hidden');
  }

  function me() { return roster.find(p => p.id === myId); }

  // --- join ---
  $('#join-btn').addEventListener('click', doJoin);
  $('#join-name').addEventListener('keydown', e => { if (e.key === 'Enter') doJoin(); });
  function doJoin() {
    const name = $('#join-name').value.trim();
    if (!name) { $('#join-error').textContent = 'Enter a fighter name!'; return; }
    initAudio(); SFX.click();
    $('#join-error').textContent = '';
    connect(name);
    showScreen('lobby');
  }

  // --- lobby ---
  function renderLobby() {
    if (phase !== 'lobby') return;
    const list = $('#lobby-players');
    list.innerHTML = '';
    roster.forEach((p, i) => {
      const li = document.createElement('li');
      li.innerHTML = `<span class="dot" style="background:${PLAYER_HUES[i % 8]}"></span>
        <span class="pname">${esc(p.name)}</span>
        ${p.host ? '<span class="tag host-tag">HOST</span>' : ''}
        ${p.id === myId ? '<span class="tag you-tag">YOU</span>' : ''}`;
      list.appendChild(li);
    });
    const m = me();
    $('#lobby-start').classList.toggle('hidden', !(m && m.host));
    $('#lobby-wait-msg').classList.toggle('hidden', !!(m && m.host));
    $('#lobby-count').textContent = `${roster.length} fighter${roster.length === 1 ? '' : 's'} in the arena`;
  }
  $('#lobby-start').addEventListener('click', () => { SFX.click(); send({ type: 'startSelect' }); });

  // --- character select ---
  const charKeys = Object.keys(CHARACTERS);
  function buildCharGrid() {
    const grid = $('#char-grid');
    charKeys.forEach(key => {
      const chr = CHARACTERS[key];
      const card = document.createElement('div');
      card.className = 'char-card';
      card.dataset.char = key;
      card.innerHTML = `
        <canvas width="150" height="170"></canvas>
        <div class="char-name" style="color:${chr.color2}">${chr.name}</div>
        <div class="char-tagline">${chr.tagline}</div>
        <div class="char-stats">
          <div>SPD ${bar(chr.speed, 340, 520)}</div>
          <div>PWR ${bar(chr.attacks.smash.dmg, 11, 19)}</div>
          <div>WGT ${bar(chr.weight, 0.82, 1.3)}</div>
        </div>
        <div class="char-picks"></div>`;
      card.addEventListener('click', () => {
        if (phase !== 'charselect') return;
        SFX.click();
        send({ type: 'pickChar', char: key });
      });
      grid.appendChild(card);
    });
  }
  function bar(v, lo, hi) {
    const n = Math.round(1 + 4 * (v - lo) / (hi - lo));
    return '<span class="bar">' + '&#9632;'.repeat(n) + '</span><span class="bar dim">' + '&#9632;'.repeat(5 - n) + '</span>';
  }

  function renderCharSelect() {
    if (phase !== 'charselect') return;
    const m = me();
    $$('.char-card').forEach(card => {
      const key = card.dataset.char;
      const picks = card.querySelector('.char-picks');
      picks.innerHTML = '';
      roster.filter(p => p.char === key && !p.spectating).forEach(p => {
        const i = roster.indexOf(p);
        const tok = document.createElement('span');
        tok.className = 'pick-token';
        tok.style.background = PLAYER_HUES[i % 8];
        tok.textContent = p.name[0].toUpperCase();
        tok.title = p.name;
        if (p.ready) tok.classList.add('ready');
        picks.appendChild(tok);
      });
      card.classList.toggle('selected', !!(m && m.char === key));
    });
    const readyBtn = $('#char-ready');
    readyBtn.disabled = !(m && m.char);
    readyBtn.textContent = m && m.ready ? 'UNREADY' : 'READY!';
    readyBtn.classList.toggle('is-ready', !!(m && m.ready));
    const waiting = roster.filter(p => !p.spectating && !p.ready).map(p => p.name);
    $('#char-status').textContent = waiting.length
      ? `Waiting for: ${waiting.join(', ')}`
      : 'Everyone ready!';
  }
  $('#char-ready').addEventListener('click', () => {
    const m = me();
    SFX.click();
    send({ type: 'ready', ready: !(m && m.ready) });
  });

  // --- map select ---
  function buildMapGrid() {
    const grid = $('#map-grid');
    Object.keys(MAPS).forEach(key => {
      const map = MAPS[key];
      const card = document.createElement('div');
      card.className = 'map-card';
      card.dataset.map = key;
      card.innerHTML = `
        <canvas width="300" height="160"></canvas>
        <div class="map-name">${map.name}</div>
        <div class="map-tagline">${map.tagline}</div>
        <div class="map-votes"></div>`;
      drawPreview(card.querySelector('canvas'), key);
      card.addEventListener('click', () => {
        if (phase !== 'mapselect') return;
        SFX.click();
        send({ type: 'voteMap', map: key });
      });
      grid.appendChild(card);
    });
  }

  function renderMapSelect() {
    if (phase !== 'mapselect') return;
    const m = me();
    $$('.map-card').forEach(card => {
      const key = card.dataset.map;
      const votes = card.querySelector('.map-votes');
      votes.innerHTML = '';
      roster.filter(p => p.vote === key && !p.spectating).forEach(p => {
        const i = roster.indexOf(p);
        const tok = document.createElement('span');
        tok.className = 'pick-token ready';
        tok.style.background = PLAYER_HUES[i % 8];
        tok.textContent = p.name[0].toUpperCase();
        votes.appendChild(tok);
      });
      card.classList.toggle('selected', !!(m && m.vote === key));
    });
    const waiting = roster.filter(p => !p.spectating && !p.vote).map(p => p.name);
    $('#map-status').textContent = waiting.length ? `Waiting for votes: ${waiting.join(', ')}` : 'Loading battle...';
  }

  // --- victory ---
  function showVictory() {
    const ov = $('#victory-overlay');
    ov.classList.remove('hidden');
    const w = roster.find(p => p.id === winnerId);
    $('#victory-name').textContent = w ? w.name : 'NO ONE';
    $('#victory-sub').textContent = w ? `${CHARACTERS[w.char] ? CHARACTERS[w.char].name : ''} WINS!` : 'It\'s a draw...';
    // celebration confetti
    for (let i = 0; i < 80; i++) {
      particles.push({
        x: (Math.random() - 0.5) * 1400, y: -600 - Math.random() * 300,
        vx: (Math.random() - 0.5) * 150, vy: 100 + Math.random() * 150,
        life: 4, max: 4, size: 5 + Math.random() * 5,
        color: PLAYER_HUES[i % 8], grav: 60
      });
    }
  }

  function esc(s) {
    const d = document.createElement('div'); d.textContent = s; return d.innerHTML;
  }

  // ---------------------------------------------------------------------------
  // Input
  // ---------------------------------------------------------------------------
  const keys = { left: 0, right: 0, up: 0, down: 0, jump: 0, jab: 0, smash: 0 };
  const KEYMAP = {
    a: 'left', arrowleft: 'left', d: 'right', arrowright: 'right',
    w: 'jump', arrowup: 'jump', ' ': 'jump',
    s: 'down', arrowdown: 'down',
    j: 'jab', z: 'jab', k: 'smash', x: 'smash'
  };

  function sendInput() { send({ type: 'input', ...keys }); }

  window.addEventListener('keydown', (e) => {
    if (e.target.tagName === 'INPUT') return;
    const k = e.key.toLowerCase();
    if (k === 'm') { musicOn = !musicOn; return; }
    const action = KEYMAP[k];
    if (!action) return;
    e.preventDefault();
    if (!keys[action]) { keys[action] = 1; sendInput(); }
  });
  window.addEventListener('keyup', (e) => {
    const action = KEYMAP[e.key.toLowerCase()];
    if (!action) return;
    if (keys[action]) { keys[action] = 0; sendInput(); }
  });
  window.addEventListener('blur', () => {
    let changed = false;
    for (const k in keys) { if (keys[k]) { keys[k] = 0; changed = true; } }
    if (changed) sendInput();
  });

  // ---------------------------------------------------------------------------
  // HUD
  // ---------------------------------------------------------------------------
  const hudCards = new Map(); // id -> element
  function renderHUD(snap) {
    const hud = $('#hud');
    if (!snap) { if (phase !== 'battle' && phase !== 'victory') { hud.innerHTML = ''; hudCards.clear(); } return; }
    for (const p of snap.players) {
      let card = hudCards.get(p.id);
      if (!card) {
        card = document.createElement('div');
        card.className = 'hud-card';
        const chr = CHARACTERS[p.char] || CHARACTERS.blaze;
        card.innerHTML = `
          <canvas width="56" height="64"></canvas>
          <div class="hud-info">
            <div class="hud-name" style="color:${chr.color2}">${esc(p.name)}</div>
            <div class="hud-dmg">0%</div>
            <div class="hud-stocks"></div>
          </div>`;
        const pc = card.querySelector('canvas').getContext('2d');
        pc.translate(28, 60); pc.scale(0.52, 0.52);
        drawFighter(pc, p.char, 'idle', 0.4, 1);
        hud.appendChild(card);
        hudCards.set(p.id, card);
      }
      const dmgEl = card.querySelector('.hud-dmg');
      dmgEl.textContent = `${p.dmg}%`;
      const heat = Math.min(1, p.dmg / 150);
      dmgEl.style.color = `rgb(255,${Math.round(255 - heat * 200)},${Math.round(255 - heat * 235)})`;
      card.querySelector('.hud-stocks').innerHTML =
        '&#9679;'.repeat(Math.max(0, p.stocks)) + '<span class="lost">' + '&#9675;'.repeat(Math.max(0, PHYS.STOCKS - p.stocks)) + '</span>';
      card.classList.toggle('dead', !p.alive);
    }
    // drop cards for players who left
    for (const [id, card] of hudCards) {
      if (!snap.players.some(p => p.id === id)) { card.remove(); hudCards.delete(id); }
    }
  }

  // ---------------------------------------------------------------------------
  // Rendering
  // ---------------------------------------------------------------------------
  const canvas = $('#game-canvas');
  const ctx = canvas.getContext('2d');
  const VIEW_W = 1600, VIEW_H = 900;
  const cam = { x: 0, y: -60, zoom: 0.85 };

  function resize() {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = VIEW_W * dpr / 2 * 2; // keep internal res fixed
    canvas.height = VIEW_H * dpr / 2 * 2;
    canvas.width = VIEW_W; canvas.height = VIEW_H;
  }
  resize();

  function interpolated() {
    if (snaps.length === 0) return null;
    if (snaps.length === 1) return snaps[0];
    const renderT = localTime() + clockOffset - 0.1;
    let a = snaps[0], b = snaps[snaps.length - 1];
    for (let i = snaps.length - 1; i > 0; i--) {
      if (snaps[i - 1].t <= renderT) { a = snaps[i - 1]; b = snaps[i]; break; }
    }
    const span = b.t - a.t;
    const u = span > 0 ? Math.max(0, Math.min(1.2, (renderT - a.t) / span)) : 1;
    const players = b.players.map(pb => {
      const pa = a.players.find(p => p.id === pb.id) || pb;
      return Object.assign({}, pb, {
        x: pa.x + (pb.x - pa.x) * u,
        y: pa.y + (pb.y - pa.y) * u
      });
    });
    return { players, countdown: b.countdown, t: b.t };
  }

  function updateCamera(players, dt) {
    const alive = players.filter(p => p.alive && !p.dead);
    if (alive.length === 0) return;
    let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
    for (const p of alive) {
      x0 = Math.min(x0, p.x); x1 = Math.max(x1, p.x);
      y0 = Math.min(y0, p.y - 100); y1 = Math.max(y1, p.y);
    }
    const pad = 280;
    const w = (x1 - x0) + pad * 2, h = (y1 - y0) + pad * 2;
    const targetZoom = Math.max(0.55, Math.min(1.0, Math.min(VIEW_W / w, VIEW_H / h)));
    const tx = (x0 + x1) / 2, ty = (y0 + y1) / 2 - 40;
    const k = 1 - Math.pow(0.02, dt);
    cam.x += (tx - cam.x) * k;
    cam.y += (ty - cam.y) * k;
    cam.zoom += (targetZoom - cam.zoom) * k;
  }

  let lastFrame = localTime();
  function frame() {
    requestAnimationFrame(frame);
    const t = localTime();
    const dt = Math.min(0.05, t - lastFrame);
    lastFrame = t;

    if (phase !== 'battle' && phase !== 'victory') return;
    if (!mapKey) return;

    const snap = interpolated();
    if (snap) updateCamera(snap.players, dt);

    // screen shake
    shake = Math.max(0, shake - dt * 60);
    const shx = (Math.random() - 0.5) * shake, shy = (Math.random() - 0.5) * shake;

    drawBackground(ctx, mapKey, VIEW_W, VIEW_H, cam, t);

    ctx.save();
    ctx.translate(VIEW_W / 2 + shx, VIEW_H / 2 + shy);
    const scale = (VIEW_H / 900) * cam.zoom;
    ctx.scale(scale, scale);
    ctx.translate(-cam.x, -cam.y);

    drawPlatforms(ctx, mapKey, t);

    // fighters
    if (snap) {
      for (const p of snap.players) {
        if (!p.alive || p.dead) continue;
        // local animation clock: smooth even between snapshots
        let st = animState.get(p.id);
        if (!st || st.anim !== p.anim || Math.abs((t - st.t0) + st.animT0 - p.animT) > 0.25) {
          st = { anim: p.anim, t0: t, animT0: p.animT };
          animState.set(p.id, st);
        }
        const animT = st.animT0 + (t - st.t0);

        ctx.save();
        ctx.translate(p.x, p.y);
        drawFighter(ctx, p.char, p.anim, animT, p.face, { invuln: p.inv });
        // name tag
        ctx.scale(1, 1);
        const idx = roster.findIndex(r => r.id === p.id);
        ctx.font = 'bold 15px Verdana, sans-serif';
        ctx.textAlign = 'center';
        ctx.fillStyle = 'rgba(0,0,0,0.45)';
        const nm = p.name;
        ctx.fillText(nm, 1, -119);
        ctx.fillStyle = PLAYER_HUES[(idx >= 0 ? idx : 0) % 8];
        ctx.fillText(nm, 0, -120);
        ctx.restore();
      }
      // off-screen indicators
      for (const p of snap.players) {
        if (!p.alive || p.dead) continue;
        const sx = (p.x - cam.x) * scale + VIEW_W / 2;
        const sy = (p.y - cam.y) * scale + VIEW_H / 2;
        if (sx < -20 || sx > VIEW_W + 20 || sy < -20 || sy > VIEW_H + 20) {
          drawOffscreenArrow(p, sx, sy, scale);
        }
      }
    }

    // particles (world space)
    for (let i = particles.length - 1; i >= 0; i--) {
      const pt = particles[i];
      pt.life -= dt;
      if (pt.life <= 0) { particles.splice(i, 1); continue; }
      pt.x += pt.vx * dt; pt.y += pt.vy * dt;
      pt.vy += pt.grav * dt;
      ctx.globalAlpha = Math.max(0, pt.life / pt.max);
      ctx.fillStyle = pt.color;
      ctx.fillRect(pt.x - pt.size / 2, pt.y - pt.size / 2, pt.size, pt.size);
    }
    ctx.globalAlpha = 1;
    ctx.restore();

    // countdown
    if (snap && snap.countdown > 0) {
      ctx.font = 'bold 160px Impact, "Arial Black", sans-serif';
      ctx.textAlign = 'center';
      ctx.fillStyle = 'rgba(255,255,255,0.95)';
      ctx.strokeStyle = 'rgba(0,0,0,0.6)';
      ctx.lineWidth = 8;
      const n = Math.ceil(snap.countdown);
      ctx.strokeText(n, VIEW_W / 2, VIEW_H / 2 - 60);
      ctx.fillText(n, VIEW_W / 2, VIEW_H / 2 - 60);
    }

    // banner
    if (banner.until > t) {
      const a = Math.min(1, (banner.until - t) * 2);
      ctx.font = 'bold 64px Impact, "Arial Black", sans-serif';
      ctx.textAlign = 'center';
      ctx.globalAlpha = a;
      ctx.strokeStyle = 'rgba(0,0,0,0.7)'; ctx.lineWidth = 6;
      ctx.strokeText(banner.text, VIEW_W / 2, VIEW_H * 0.3);
      ctx.fillStyle = banner.color;
      ctx.fillText(banner.text, VIEW_W / 2, VIEW_H * 0.3);
      ctx.globalAlpha = 1;
    }
  }

  function drawOffscreenArrow(p, sx, sy, scale) {
    const margin = 36;
    const cx = Math.max(margin, Math.min(VIEW_W - margin, sx));
    const cy = Math.max(margin, Math.min(VIEW_H - margin, sy));
    const ang = Math.atan2(sy - cy, sx - cx);
    const chr = CHARACTERS[p.char] || CHARACTERS.blaze;
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(ang);
    ctx.fillStyle = chr.color2;
    ctx.beginPath();
    ctx.moveTo(16, 0); ctx.lineTo(-8, -11); ctx.lineTo(-8, 11);
    ctx.closePath(); ctx.fill();
    ctx.rotate(-ang);
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 13px Verdana';
    ctx.textAlign = 'center';
    ctx.fillText(`${p.dmg}%`, 0, 28);
    ctx.restore();
  }

  // ---------------------------------------------------------------------------
  buildCharGrid();
  buildMapGrid();
  showScreen('join');
  requestAnimationFrame(frame);

  // animated character preview on the join screen
  const joinCv = $('#join-preview');
  if (joinCv) {
    const jctx = joinCv.getContext('2d');
    setInterval(() => {
      jctx.clearRect(0, 0, joinCv.width, joinCv.height);
      const t = localTime();
      const keys2 = Object.keys(CHARACTERS);
      keys2.forEach((k, i) => {
        jctx.save();
        jctx.translate(70 + i * 110, 150);
        const anims = ['idle', 'run', 'idle', 'jab'];
        drawFighter(jctx, k, anims[(Math.floor(t / 3) + i) % anims.length], t, 1);
        jctx.restore();
      });
    }, 1000 / 30);
  }

  // character preview animations on the select screen
  setInterval(() => {
    if (phase !== 'charselect') return;
    const t = localTime();
    $$('.char-card').forEach((card, i) => {
      const cv = card.querySelector('canvas');
      const c = cv.getContext('2d');
      c.clearRect(0, 0, cv.width, cv.height);
      c.save();
      c.translate(cv.width / 2, cv.height - 14);
      c.scale(1.15, 1.15);
      const selected = card.classList.contains('selected');
      drawFighter(c, card.dataset.char, selected ? 'jab' : 'idle', selected ? (t % 0.6) : t, 1);
      c.restore();
    });
  }, 1000 / 30);
})();
